<?php

declare(strict_types=1);

namespace Xkhm\Service;

/**
 * The server modules — the plugins that provision a server.
 *
 * The `tblservers.type` holds the module: the plugin that creates the
 * account on the machine, configures the hosting, and renews it.
 * Without it, a server is just a hostname.
 *
 * The list comes from the original installation's `modules/servers/`
 * directory (the same place the WHMCS's own `configservers` page
 * reads it from) and is generated by
 * `tools/extract_server_modules.py` into
 * `resources/whmcs_server_modules.php`.
 */
final class ServerTypes
{
    /**
     * The modules, as `identifier => name`.
     *
     * @return array<string, string>
     */
    public static function all(): array
    {
        $file = dirname(__DIR__, 2) . '/resources/whmcs_server_modules.php';

        if (!is_file($file)) {
            return [];
        }

        $data = require $file;

        $modules = $data['modules'] ?? [];

        return is_array($modules) ? $modules : [];
    }

    /**
     * The name of a module.
     *
     * A module that is not in the list keeps its identifier — que é
     * melhor do que um nome inventado.
     */
    public static function name(string $type): string
    {
        $type = trim($type);

        if ($type === '') {
            return '';
        }

        return self::all()[$type] ?? $type;
    }
}
